ddls.sql:

-- Remove the virtual-directory mapping and the clean-URL rules; the DAV
-- resources are removed by the VAD engine.  Each is guarded on its own,
-- so a deploy that never ran, or one from before the rules existed,
-- still uninstalls cleanly.
{
  declare exit handler for sqlstate '*' { ; };
  DB.DBA.VHOST_REMOVE (lpath => '/vvec/');
}
{
  declare exit handler for sqlstate '*' { ; };
  delete from DB.DBA.URL_REWRITE_RULE_LIST where URRL_LIST = 'vvec_rule_list';
  delete from DB.DBA.URL_REWRITE_RULE where URR_RULE like 'vvec_rule_%';
}
-- Sign-in sessions: stop the sweeper and drop the store.  Sessions are
-- ephemeral by definition, so there is nothing here worth keeping once
-- the console is gone.
{
  declare exit handler for sqlstate '*' { ; };
  delete from DB.DBA.SYS_SCHEDULED_EVENT where SE_NAME = 'VVEC_SESSION_GC';
}
{
  declare exit handler for sqlstate '*' { ; };
  exec ('drop table DB.DBA.VVEC_SESSION');
}
